'et.k_welcome' => 'Welcome — first connection (portal accounts)',
'et.d_s_welcome' => 'Your access to the Golden A/S portal',
'et.d_b_welcome' => "Dear {name},\n\nYour account on the Golden A/S portal is ready. Please follow these three steps.\n\n1. FIRST SIGN-IN\n   Open {url} and sign in with your e-mail {email} and the temporary password that we give you separately (by phone or in a second message — never in this e-mail).\n\n2. CHANGE YOUR PASSWORD\n   After the first sign-in click your avatar at the top right (My Account) and set your own password under New password: at least 10 characters, not used anywhere else.\n\n3. ENABLE TWO-FACTOR AUTHENTICATION (2FA)\n   In My Account › Two-factor authentication scan the QR code with an authenticator app (Microsoft Authenticator, Google Authenticator, Authy, …) and enter the 6-digit code to confirm. From then on every sign-in asks for the code of the app in addition to your password.\n\nFive wrong passwords lock the account for 15 minutes; if you cannot sign in, reply to this e-mail and we will unlock it or reset the password.\n\n{signature}",
