'eng.settings' => 'Stage sections',
'eng.settings_lede' => 'The hour-budgeted sections of the process line — Engineering (Electrical, Automation, Mechanical, UI/UX, IT), Production, Field & Installation, HAT / SAT, Commissioning — and the disciplines that feed them. A section\'s budget is the budgeted hours of its disciplines in the sub-project\'s Budget & actual; its actual hours are the hours of the same disciplines booked on that stage. One source — agreed with the customer; approved extra hours are shown over it, never added to it.',
