'eng.map_hint' => 'Tick the sections each discipline feeds. Engineering disciplines feed one engineering section; an installer feeds Field & Installation and HAT / SAT; a service or automation engineer HAT / SAT and Commissioning. A discipline that feeds several sections gets one budget cell per section in Budget & actual, and the stage chosen on the timesheet line decides where its hours count. Management and sales disciplines stay unmapped.',
